INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(5701, 'Joshua 13:7', 'Joshua', 13, 7, '&nbsp;نو اوس دا زمکه په هغه نورو نهو قبيلو او د منسى په نيمه قبيله باندې تقسيم کړه چې د هغوئ خپل ميراث شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5702, 'Joshua 13:8', 'Joshua', 13, 8, '&nbsp;د روبين، جاد او د منسى نيمې قبيلې د مخکښې نه هغه زمکه اخستې وه کومه چې موسىٰ، د مالِک خُدائ خِدمتګار هغوئ له ورکړې وه، دا د اُردن سيند نمرخاتۀ طرف ته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5703, 'Joshua 13:9', 'Joshua', 13, 9, '&nbsp;د هغوئ علاقه د ارنون وادۍ په غاړه تر عروعير او د هغه وادۍ په مينځ کښې ښار پورې خوره شوه او په دې کښې د ميدبا نه واخله تر ديبون پورې ټولې اوچتې علاقې شاملې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5704, 'Joshua 13:10', 'Joshua', 13, 10, '&nbsp;دا د عمون سرحد پورې لاړه او هغه ټول ښارونه په کښې شامل وُو په کومو باندې چې امورى بادشاه سيحون حکومت کړے وو، چې هغۀ په حسبون کښې بادشاهى کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5705, 'Joshua 13:11', 'Joshua', 13, 11, '&nbsp;په دې کښې د جِلعاديانو، د جسوريانو او د معکيانو علاقې، د حرمون ټول غر او تر سلکه پورې ټول بسن شامل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5706, 'Joshua 13:12', 'Joshua', 13, 12, '&nbsp;په کښې د عوج بادشاهى هم شامله وه کوم چې د رفائيم آخرى پاتې شوے وو، چې هغۀ په عستارات او ادرعى باندې بادشاهى کړې وه. موسىٰ دې خلقو له شکست ورکړے وو او هغوئ يې شړلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5707, 'Joshua 13:13', 'Joshua', 13, 13, '&nbsp;خو بنى اِسرائيلو د جسور او معکه خلق نۀ وُو شړلى، هغوئ تر اوسه پورې د بنى اِسرائيلو سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5708, 'Joshua 13:14', 'Joshua', 13, 14, '&nbsp;موسىٰ د ليوى قبيلې له په ميراث کښې هيڅ زمکه نۀ وه ورکړې، لکه څنګه چې مالِک خُدائ موسىٰ ته فرمائيلى وُو چې ليويانو ته به د خپلې برخې په توګه هغه قربانۍ ملاويږى کومې چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک ته په قربان‌ګاه باندې سوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5709, 'Joshua 13:15', 'Joshua', 13, 15, '&nbsp;موسىٰ د هغه مُلک يوه حِصه د روبين د قبيلې کورَنو له ورکړې وه چې د هغوئ ميراث شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5710, 'Joshua 13:16', 'Joshua', 13, 16, '&nbsp;د هغوئ علاقه د ارنون وادۍ په غاړه د عروعير پورې او د هغه وادۍ تر مينځ ښار پورې خوره وه او په دې کښې د ميدبا نه ګېرچاپېره ټولې اوچتې علاقې شاملې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5711, 'Joshua 13:17', 'Joshua', 13, 17, '&nbsp;په دې کښې حسبون او د اوچتې علاقې ټول ښارونه شامل وُو يعنې ديبون، بامات بعل، بيت‌بعل معون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5712, 'Joshua 13:18', 'Joshua', 13, 18, '&nbsp;يهض، قديمات، مفعت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5713, 'Joshua 13:19', 'Joshua', 13, 19, '&nbsp;قِريَتائم، سبماه او په وادۍ کښې په غر باندې ضره‌سحر،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5714, 'Joshua 13:20', 'Joshua', 13, 20, '&nbsp;بيت‌فعور، د پِسګه غر ښکته علاقې او بيت‌يسيموت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5715, 'Joshua 13:21', 'Joshua', 13, 21, '&nbsp;په دې کښې د اوچتې علاقې ټول ښارونه او د امورى بادشاه سيحون ټول مُلک شامل وو، امورى بادشاه سيحون په حسبون بادشاهى کړې وه. موسىٰ هغۀ له او دغسې د ميديان دې حکمرانانو له هم شکست ورکړو، ايوى، رِقم، صور، حُور او رِبع. د سيحون په مُلک کښې دې ټولو بادشاهانو حکومت کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5716, 'Joshua 13:22', 'Joshua', 13, 22, '&nbsp;کوم خلق چې بنى اِسرائيلو ووژل په هغې کښې د بعور زوئ بلعام فال کتونکے هم شامل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5717, 'Joshua 13:23', 'Joshua', 13, 23, '&nbsp;نمرپرېواتۀ طرف ته د اُردن سيند د روبين قبيلې سرحد وو. دا هغه ښارونه او کلى وُو چې د روبين قبيلې کورَنو له ورکړے شوى وُو چې د هغوئ خپل ميراث شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5718, 'Joshua 13:24', 'Joshua', 13, 24, '&nbsp;موسىٰ د هغه مُلک يوه حِصه د جاد قبيلې کورَنو له هم ورکړې وه چې د هغوئ خپل ميراث شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5719, 'Joshua 13:25', 'Joshua', 13, 25, '&nbsp;د هغوئ په علاقه کښې يعزير او د جِلعاد ټول ښارونه، د عروعير پورې د عمونيانو نيم مُلک شامل وو، کوم چې د ربه نمرخاتۀ طرف ته دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5720, 'Joshua 13:26', 'Joshua', 13, 26, '&nbsp;د هغوئ مُلک د حسبون نه تر رامت مصفاه او بطونيم پورې او د محنايم نه تر دبير سرحد پورې خور وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5721, 'Joshua 13:27', 'Joshua', 13, 27, '&nbsp;د اُردن په وادۍ کښې په دې کښې بيت‌هارم، بيت‌نِمره، سُکات، صفون او د حسبون بادشاه سيحون باقى پاتې بادشاهى شامله وه. د هغوئ نمرپرېواتۀ طرف ته سرحد د ګليل درياب پورې د اُردن سيند وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5722, 'Joshua 13:28', 'Joshua', 13, 28, '&nbsp;دا هغه ښارونه او کلى وُو کوم چې د جاد قبيلې کورَنو له ورکړے شوى وُو چې د هغوئ خپل ميراث شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5723, 'Joshua 13:29', 'Joshua', 13, 29, '&nbsp;موسىٰ د هغه مُلک يوه حِصه د منسى نيمې قبيلې کورَنو له ورکړې وه چې د هغوئ خپل ميراث شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5724, 'Joshua 13:30', 'Joshua', 13, 30, '&nbsp;د هغوئ علاقه تر محنايم پورې خوره وه او په دې کښې ټول بسن، د بسن بادشاه عوج ټوله بادشاهى او هم داسې په بسن کښې د يائير ټول شپېتۀ کلى هم شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5725, 'Joshua 13:31', 'Joshua', 13, 31, '&nbsp;په کښې نيم جِلعاد او هم داسې عستارات او ادرعى، په بسن کښې د عوج په بادشاهۍ کښې ښارونه هم شامل وُو. دا ټول د منسى زوئ مکير اولاد نيمو کورَنو له ورکړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5726, 'Joshua 13:32', 'Joshua', 13, 32, '&nbsp;کله چې موسىٰ د موآب په مېدانونو کښې وو نو هغۀ د يريحو نمرخاتۀ طرف ته او د اُردن مُلک داسې تقسيم کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5727, 'Joshua 13:33', 'Joshua', 13, 33, '&nbsp;خو موسىٰ ليوى قبيلې له په ميراث کښې هيڅ هم ورنۀ کړل. ځکه چې مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د هغوئ ميراث دے لکه څنګه چې هغۀ ورسره وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5728, 'Joshua 14:1', 'Joshua', 14, 1, '&nbsp;دا هغه حِساب کِتاب دے چې د اُردن سيند نمرپرېواتۀ طرف ته د کنعان مُلک په بنى اِسرائيلو باندې څنګه تقسيم شوے وو. اِلى‌عزر اِمام، د نون زوئ يشوَع او د بنى اِسرائيلو د قبيلو کورَنو مشرانو دا په خلقو باندې تقسيم کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5729, 'Joshua 14:2', 'Joshua', 14, 2, '&nbsp;لکه څنګه چې مالِک خُدائ موسىٰ له حُکم ورکړے وو چې د اُردن سيند نمرپرېواتۀ طرف ته نهه نيمو قبيلو ته د ميراث د مِلاوېدو دا فېصله دې د پچې په ذريعه وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5730, 'Joshua 14:5', 'Joshua', 14, 5, '&nbsp;بنى اِسرائيلو هغه زمکه هم هغه شان تقسيم کړه لکه څنګه چې مالِک خُدائ موسىٰ له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5731, 'Joshua 14:6', 'Joshua', 14, 6, '&nbsp;يوه ورځ د يهوداه د قبيلې څۀ خلق په جِلجال کښې يشوَع له راغلل. د هغوئ نه يو کس د يفُنه قنزى زوئ کالب هغۀ ته وفرمائيل، ”تا ته پته ده چې مالِک خُدائ په قادِس برنيع کښې د خُدائ پاک بنده موسىٰ ته زما او ستا په حقله څۀ فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5732, 'Joshua 14:7', 'Joshua', 14, 7, '&nbsp;زۀ د څلوېښتو کالو وم چې کله د مالِک خُدائ خِدمت کوونکى موسىٰ زۀ د قادِس برنيع نه ولېږلم چې د مُلک معلومات حاصل کړم. نو ما هغۀ له صحيح خبر راوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5733, 'Joshua 14:8', 'Joshua', 14, 8, '&nbsp;کوم سړى چې زما سره تلى وُو نو هغوئ زمونږ خلق يرول. خو ما په وفادارۍ سره د مالِک خُدائ زما د خُدائ پاک تابعدارى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5734, 'Joshua 14:9', 'Joshua', 14, 9, '&nbsp;په هغه وخت موسىٰ ما سره دا لوظ وکړو چې ما او زما بچو ته به بې‌شکه دا مُلک د ميراث په توګه ملاويږى چې په کوم کښې ما قدم اېښے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5735, 'Joshua 14:10', 'Joshua', 14, 10, '&nbsp;خو اوس ګوره، چې د کله نه مالِک خُدائ موسىٰ ته داسې فرمائيلى دى نو د هغې پينځۀ څلوېښت کاله وشول. دا هغه وخت وو چې کله بنى اِسرائيل په صحرا کښې روان وُو او مالِک خُدائ د خپلې وعدې په مطابق تر نن ورځې پورې زۀ ژوندے ساتلے يم. ما ته وګوره. زۀ د پينځۀ اتياو کالو يم', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5736, 'Joshua 14:11', 'Joshua', 14, 11, '&nbsp;او زۀ نن هم هغه شان تکړه يم چې څنګه په هغه وخت کښې وم چې کله موسىٰ لېږلے وم. زۀ تر اوسه پورې د جنګ او د باقى نورو کارونو دپاره اوس هم ښۀ تکړه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5737, 'Joshua 14:12', 'Joshua', 14, 12, '&nbsp;نو، ما له د غرونو هغه مُلک راکړه چې مالِک خُدائ په هغه ورځ زما سره د هغې وعده کړې وه په کومه ورځ چې ما او نورو جاسوسانو خبر راوړو. ما بيا تا ته ووئيل چې هلته د دېوانو نسل عناقيان د پَخو دېوالونو په لويو لويو ښارونو کښې وُو. مالِک خُدائ دې زما مل شى او هغوئ به زۀ وشړم، هم هغه شان لکه څنګه چې مالِک خُدائ فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5738, 'Joshua 14:13', 'Joshua', 14, 13, '&nbsp;يشوَع د يفُنه زوئ کالب دپاره برکت وغوښتلو او د حبرون ښار يې ورکړو چې د هغۀ خپل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5739, 'Joshua 14:14', 'Joshua', 14, 14, '&nbsp;حبرون تر اوسه پورې د يفُنه قنزى د زوئ کالب دے، ځکه چې هغۀ په وفادارۍ سره د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک تابعدارى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5740, 'Joshua 14:15', 'Joshua', 14, 15, '&nbsp;د حبرون ښار مخکښې د قِريَت‌اربع په نوم يادېدو، ځکه چې اربع د ټولو نه لوئ عناقے وو. نو بيا په هغه مُلک کښې جنګونه ختم شول او امن و امان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5741, 'Joshua 15:1', 'Joshua', 15, 1, '&nbsp;د يهوداه قبيلې کورَنو ته د زمکې يوه حِصه مِلاو شوه چې داسې بيان شوې ده، هغه مُلک په جنوب کښې د ادوم د سرحد سره د صين صحرا آخرى جنوبى سر ته ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5742, 'Joshua 15:2', 'Joshua', 15, 2, '&nbsp;دا جنوبى سرحد د مالګې درياب د جنوبى سر نه لاړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5743, 'Joshua 15:3', 'Joshua', 15, 3, '&nbsp;او په جنوب کښې د لړم درې نه واخله تر صين پورې تلے وو. دا په جنوب کښې د قادِس برنيع نه تلے وو، د حصرون نه تېر وو او ادار ته رسېدلے وو او قرقع ته تاو وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5744, 'Joshua 15:4', 'Joshua', 15, 4, '&nbsp;او عضمون ته تلے وو او د مديترانى د سمندر ته د مِصر په سرحد باندې په نِهر باندې تلے وو، سرحد هلته ختم شوے وو. دا د يهوداه جنوبى سرحد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5745, 'Joshua 15:5', 'Joshua', 15, 5, '&nbsp;نمرخاتۀ طرف ته سرحد يې د مالګې درياب وو، دا تر هغه خليج پورې تلے وو چرته چې د اُردن سيند خالى کيږى. شمالى سرحد د هغه ځائ نه شروع کېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5746, 'Joshua 15:6', 'Joshua', 15, 6, '&nbsp;چې د بيت‌حجلاه پورې خور وو او د هغه غاړې په شمالى طرف تلے وو چې د هغې نه د اُردن وادى ښکارېده. بيا دا بوهن کاڼى پورې تلے وو، بوهن د روبين زوئ وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5747, 'Joshua 15:7', 'Joshua', 15, 7, '&nbsp;د مصيبت د وادۍ نه تر دبير پورې او بيا په شمال کښې د جِلجال طرف ته تاو وو، چې مخ يې د وادۍ جنوبى طرف ته د ادميم درې ته دے. دا د عين‌شمس د چينو نه عين‌راجل ته تلے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5748, 'Joshua 15:8', 'Joshua', 15, 8, '&nbsp;کوم چې د غرۀ جنوبى طرف ته د هنوم وادۍ نه تېر شوے وو چرته چې د يبوسيانو يروشلم ښار وو. سرحد بيا د هنوم وادۍ نمرپرېواتۀ طرف ته پاس غر ته ختلے وو، چې د رفائيم وادۍ شمالى سر سره دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5749, 'Joshua 15:9', 'Joshua', 15, 9, '&nbsp;د هغه ځائ نه دا د نفتوح چينو ته او بهر د عِفرون سره نزدې ښارونو ته تلے وو. دا هلته د بعله يعنې قِريَت‌يعريم طرف ته تاو وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5750, 'Joshua 15:10', 'Joshua', 15, 10, '&nbsp;چرته چې دا د ادوم د غرونو مُلک طرف ته د بعله نمرپرېواتۀ طرف ته تاو وو، د يعريم يعنې کسلون غرۀ شمالى طرف ته، لاندې بيت‌شمس ته تلے وو او د تمنت نه تېر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5751, 'Joshua 15:11', 'Joshua', 15, 11, '&nbsp;سرحد بيا د عقرون شمالى طرف ته غرۀ ته تلے وو، د سکرون طرف ته تاو وو، د بعله غر نه تېر وو او يبنى‌اېل ته تلے وو. دا د مديترانى د سمندر سره ختم وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5752, 'Joshua 15:12', 'Joshua', 15, 12, '&nbsp;چې د هغې نه نمرپرېواتۀ طرف ته د مديترانى سمندر وو. په دې سرحدونو کښې د يهوداه د قبيلو خلق اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5753, 'Joshua 15:13', 'Joshua', 15, 13, '&nbsp;لکه څنګه چې مالِک خُدائ يشوَع ته حُکم کړے وو، د يهوداه د علاقې يوه حِصه د يفُنه زوئ کالب له ورکړے شوې وه. هغۀ ته حبرون مِلاو شو، د هغه ښار نوم قِريَت‌اربع وو او اربع د عناقيانو پلار نيکۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5754, 'Joshua 15:14', 'Joshua', 15, 14, '&nbsp;کالب د عناقيانو هغه اولاد د ښار نه وويستلو، چې د سيسى، اخيمان او تلمى قبيلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5755, 'Joshua 15:15', 'Joshua', 15, 15, '&nbsp;د هغې ځائ نه هغه لاړو چې د دبير په اوسېدونکو باندې حمله وکړى. هغه ښار مخکښې قِريَت‌سِفر بللے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5756, 'Joshua 15:16', 'Joshua', 15, 16, '&nbsp;کالب وفرمائيل، ”زۀ به خپله لور عکسه هغه سړى له ورکړم چې وادۀ يې کړى چې کوم سړے د قِريَت‌سِفر په قبضه کولو کښې کامياب شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5757, 'Joshua 15:17', 'Joshua', 15, 17, '&nbsp;د کالب ورارۀ او د قنز زوئ عتنى‌اېل هغه ښار قبضه کړو، نو کالب خپله عکسه لور هغۀ ته وادۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5758, 'Joshua 15:18', 'Joshua', 15, 18, '&nbsp;د وادۀ په ورځ هغې عتنى‌اېل دې ته رضا کولو چې د هغې د پلار نه يو پټے وغواړى. هغه د خپل خر نه کوزه شوه او کالب ترې نه تپوس وکړو چې، ”تۀ څۀ غواړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5759, 'Joshua 15:19', 'Joshua', 15, 19, '&nbsp;هغې ورته ووئيل، ”زما سره ښۀ وکړه، زۀ د اوبو يو څو چينې غواړم. تا چې ما له کومه زمکه راکړې ده هغه په اوچ مُلک کښې ده.“ نو کالب هغې له بره او ښکته چينې ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
